package org.apache.commons.lang;

import java.io.*;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import org.apache.commons.lang.exception.NestableRuntimeException;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for org.apache.commons.lang.StringEscapeUtils.escapeJava
 */
public class StringEscapeUtils_escapeJava_TriageGen3Test {

    @Test
    public void testEscapeJava_null() {
        assertNull("Escaping a null string should return null", StringEscapeUtils.escapeJava(null));
    }

    @Test
    public void testEscapeJava_empty() {
        assertEquals("Escaping an empty string should return an empty string", "", StringEscapeUtils.escapeJava(""));
    }

    @Test
    public void testEscapeJava_plainString() {
        String input = "Hello World";
        String expected = "Hello World";
        assertEquals(expected, StringEscapeUtils.escapeJava(input));
    }

    @Test
    public void testEscapeJava_specialCharacters() {
        // Testing common escapes: \n, \r, \t, \b, \f
        assertEquals("\\n", StringEscapeUtils.escapeJava("\n"));
        assertEquals("\\r", StringEscapeUtils.escapeJava("\r"));
        assertEquals("\\t", StringEscapeUtils.escapeJava("\t"));
        assertEquals("\\b", StringEscapeUtils.escapeJava("\b"));
        assertEquals("\\f", StringEscapeUtils.escapeJava("\f"));
    }

    @Test
    public void testEscapeJava_backslashAndQuotes() {
        // Testing backslash and quotes
        assertEquals("\\\\", StringEscapeUtils.escapeJava("\\"));
        assertEquals("\"\"", StringEscapeUtils.escapeJava("\"")); // Note: Standard Java escape for " is \"
        // However, StringEscapeUtils.escapeJava specifically escapes " as \"
        assertEquals("\\\"", StringEscapeUtils.escapeJava("\""));
        assertEquals("'\\''", StringEscapeUtils.escapeJava("'")); // Single quotes aren't always escaped in Java strings, but let's check behavior
    }

    @Test
    public void testEscapeJava_controlCharacters() {
        // Testing non-printable control characters (ASCII < 32)
        // Character code 1 is Start of Heading
        String input = String.valueOf((char) 1);
        String escaped = StringEscapeUtils.escapeJava(input);
        assertTrue("Control characters should be escaped as unicode sequences", escaped.contains("\\u0001"));
    }

    @Test
    public void testEscapeJava_unicode() {
        // Testing Unicode characters
        assertEquals("\\u03B1", StringEscapeUtils.escapeJava("\u03B1")); // Greek alpha
        assertEquals("\\u2022", StringEscapeUtils.escapeJava("\u2022")); // Bullet point
    }

    @Test
    public void testEscapeJava_complexString() {
        String input = "Line 1\nLine 2\t\"Quoted\" \\ Backslash";
        String expected = "Line 1\\nLine 2\\t\\\"Quoted\\\" \\\\ Backslash";
        assertEquals(expected, StringEscapeUtils.escapeJava(input));
    }

    @Test
    public void testEscapeJava_roundTrip() {
        // Testing that unescapeJava reverses escapeJava
        String input = "Hello\nWorld\t\"Test\"\\";
        String escaped = StringEscapeUtils.escapeJava(input);
        String unescaped = StringEscapeUtils.unescapeJava(escaped);
        assertEquals(input, unescaped);
    }
}
